library(glmmTMB)
library(dplyr)
library(tidyr)
library(ggplot2)
library(broom.mixed)
library(performance)
library(gt)
library(readr)
library(DHARMa)
library(ggeffects)
library(titanic)





titanic &lt;- titanic_train

# Keep the same complete-case sample for every model
titanic &lt;- titanic |&gt;
  select(Survived, Sex, Age, Pclass) |&gt;
  drop_na() |&gt;
  mutate(
    Sex.Binary = case_when(
      Sex == "male" ~ 0,
      Sex == "female" ~ 1
    )
  ) |&gt;
  mutate(
    Survived.Char = case_when(
      Survived == 0 ~ "Died",
      Survived == 1 ~ "Survived"
    )
  ) |&gt;
  mutate(
    Pclass.Char = case_when(
      Pclass == 1 ~ "First Class",
      Pclass == 2 ~ "Second Class",
      Pclass == 3 ~ "Third Class"
    )
  ) |&gt;
  mutate(Pclass = factor(Pclass, levels = c(1, 2, 3))) |&gt;
  select(Survived, Survived.Char, Sex, Sex.Binary, Pclass, Pclass.Char, Age)

n &lt;- nrow(titanic)







descriptives &lt;- titanic |&gt;
  summarise(
    across(
      c(Age),
      list(mean = mean, sd = sd, min = min, max = max)
    )
  ) |&gt;
  pivot_longer(
    everything(),
    names_to = c("variable", ".value"),
    names_sep = "_"
  )

descriptives |&gt;
  gt() |&gt;
  fmt_number(columns = where(is.numeric), decimals = 2)



