survival_counts &lt;- titanic |&gt;
  count(Survived.Char) |&gt;
  mutate(
    Group = "Survival Status",
    Category = Survived.Char
  ) |&gt;
  select(Group, Category, n)

sex_counts &lt;- titanic |&gt;
  count(Sex) |&gt;
  mutate(
    Group = "Sex",
    Category = Sex
  ) |&gt;
  select(Group, Category, n)

class_counts &lt;- titanic |&gt;
  count(Pclass.Char) |&gt;
  mutate(
    Group = "Passenger Class",
    Category = Pclass.Char
  ) |&gt;
  select(Group, Category, n)

bind_rows(survival_counts, sex_counts, class_counts) |&gt;
  gt(groupname_col = "Group") |&gt;
  cols_label(
    Category = "Category",
    n = "Frequency"
  )



