sex_table &lt;- titanic |&gt;
  count(Sex, Survived.Char) |&gt;
  pivot_wider(names_from = Survived.Char, values_from = n, values_fill = 0) |&gt;
  mutate(Group = "Sex", Category = Sex) |&gt;
  select(Group, Category, Died, Survived)

class_table &lt;- titanic |&gt;
  count(Pclass.Char, Survived.Char) |&gt;
  pivot_wider(names_from = Survived.Char, values_from = n, values_fill = 0) |&gt;
  mutate(Group = "Passenger Class", Category = Pclass.Char) |&gt;
  select(Group, Category, Died, Survived)

bind_rows(sex_table, class_table) |&gt;
  gt(groupname_col = "Group") |&gt;
  cols_label(Category = "Category", Died = "Died", Survived = "Survived")



